export type Level = 'warning' | 'error' | 'fatal' | 'info';

export type ReportingOptions = {
	level?: Level;
	name?: string;
	statusCode?: number;
};

export class ApplicationError extends Error {
	level: Level;
	name: string;
	statusCode?: number;

	constructor(
		message: string,
		{ level, name, statusCode, cause }: Partial<ErrorOptions> & ReportingOptions = {},
	) {
		super(message, cause !== undefined ? { cause } : undefined);
		this.level = level ?? 'error';
		this.name = name ?? 'AIServiceSDKError';
		this.statusCode = statusCode;
	}
}

export class APIResponseError extends ApplicationError {
	/**
	 * Machine-readable error class from the response body's `error.type`, when present
	 * (e.g. `'quota_exhausted'`). Lets consumers branch on the code instead of the message.
	 */
	errorCode?: string;

	constructor(message: string, statusCode?: number, errorCode?: string) {
		// Expected client errors (4xx) are downgraded to 'warning' so consumers
		// (e.g. n8n) can filter them out of error reporting. Server errors and
		// malformed responses keep 'error'.
		const isClientError = statusCode !== undefined && statusCode >= 400 && statusCode < 500;
		super(message, {
			name: 'AIServiceAPIResponseError',
			level: isClientError ? 'warning' : 'error',
			statusCode,
		});
		this.errorCode = errorCode;
	}
}

export class AuthError extends ApplicationError {
	constructor(message: string) {
		super(message, { name: 'AuthError', level: 'warning' });
	}
}

/**
 * `fetch()` rejected before the service answered: DNS, refused connection, TLS, timeout.
 * The service is unreachable rather than broken, so the level is 'warning' and consumers
 * can map it to 503. undici only says `fetch failed`; the real reason sits on `cause`, so
 * its innermost message is appended and the original error is kept as `cause`.
 */
export class NetworkError extends ApplicationError {
	constructor(cause: unknown) {
		super(`Could not reach the AI assistant service: ${rootCauseMessage(cause)}`, {
			name: 'AIServiceNetworkError',
			level: 'warning',
			cause,
		});
	}
}

function rootCauseMessage(error: unknown): string {
	let current = error;
	while (current instanceof Error && current.cause instanceof Error) {
		current = current.cause;
	}
	return current instanceof Error ? current.message : String(current);
}
